```js
import { EventEmitter } from 'node:events';
import { platform } from 'node:os';

const isDarwin = platform() === 'darwin';

export class FileWatcher extends EventEmitter {
  #stream = null;
  #watcher = null;
  #path;

  constructor(path, options = {}) {
    super();
    this.#path = path;
    this.options = options;
  }

  async start() {
    if (isDarwin) {
      await this.#startFsevents();
    } else {
      this.#startPortable();
    }
    return this;
  }

  async #startFsevents() {
    let fsevents;
    try {
      ({ default: fsevents } = await import('fsevents'));
    } catch {
      this.#startPortable();
      return;
    }
    const flags = fsevents.constants;
    this.#stream = fsevents.watch(this.#path, (eventPath, eventFlags, eventId) => {
      this.emit('change', {
        path: eventPath,
        id: eventId,
        type: classify(eventFlags, flags),
        flags: eventFlags,
      });
    }, this.options);
  }

  #startPortable() {
    const { watch } = await import('node:fs') // need top
    this.#watcher = watch(this.#path, { recursive: true }, (eventType, filename) => {
      this.emit('change', { path: filename, type: eventType, id: null, flags: 0 });
    });
  }

  stop() {
    if (this.#stream) { this.#stream.stop(); this.#stream = null; }
    if (this.#watcher) { this.#watcher.close(); this.#watcher = null; }
  }
}
